```java
class ShoppingCartTest {
    private ShoppingCart cart;

    @BeforeEach
    void setUp() {                 // runs before EVERY test
        cart = new ShoppingCart(); // each test gets an empty cart
    }

    @Test
    void newCartIsEmpty() {
        assertEquals(0, cart.itemCount());
    }

    @Test
    void addingItemIncreasesCount() {
        cart.add(new Item("book", 10.0));
        assertEquals(1, cart.itemCount()); // not polluted by other tests
    }

    @AfterEach
    void tearDown() {              // runs after EVERY test, even on failure
        cart.clear();
    }
}
```

```java
@DisplayName("BankAccount")
class BankAccountTest {

    @Test
    @DisplayName("new account starts with a zero balance")
    void newAccountZeroBalance() {
        assertEquals(0, new BankAccount().balance());
    }

    @Test
    @DisplayName("rejects a withdrawal larger than the balance")
    void rejectsOverdraw() {
        var account = new BankAccount();
        assertThrows(InsufficientFundsException.class, () -> account.withdraw(50));
    }
}
// Report shows: BankAccount > rejects a withdrawal larger than the balance
