```java
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.junit.jupiter.MockitoExtension;
import org.mockito.Mock;
import org.mockito.InjectMocks;

@ExtendWith(MockitoExtension.class)  // can add more, e.g. @ExtendWith(SpringExtension.class)
class OrderServiceTest {
    @Mock OrderRepository repo;       // initialized by the extension
    @InjectMocks OrderService service;
}
```
Without `@ExtendWith(MockitoExtension.class)`, the `@Mock` fields stay `null` and you get a `NullPointerException`.

```java
@DisplayName("BankAccount")
class BankAccountTest {
    BankAccount account;
    @BeforeEach void create() { account = new BankAccount(); } // runs first

    @Nested
    @DisplayName("when empty")
    class WhenEmpty {
        @Test void balanceIsZero() { assertEquals(0, account.balance()); }
    }

    @Nested
    @DisplayName("when funded with 100")
    class WhenFunded {
        @BeforeEach void deposit() { account.deposit(100); } // runs AFTER create()
        @Test void allowsWithdrawal() {
            account.withdraw(40);
            assertEquals(60, account.balance());
        }
    }
}
// Report: BankAccount > when funded with 100 > allowsWithdrawal
```
